// Aggregate all data for Agent 6
const aggregatedData = {
  questionnaire: $node['Webhook - Receive Questionnaire'].json.questionnaire,
  personas: $node['Agent 1: Psychologist & Persona'].json.personas,
  historical: $node['Agent 2: Cocktail Historian'].json.historicalRecommendations,
  cocktails: $node['Agent 3: Master Mixologist'].json.cocktails,
  presentation: $node['Agent 4: Visual Presenter'].json.presentation,
  stories: $node['Agent 5: Storyteller'].json.stories
};

// Prepare prompts for image generation
const imagePrompts = [];

if (aggregatedData.cocktails && aggregatedData.cocktails.cocktails) {
  aggregatedData.cocktails.cocktails.forEach((cocktail, index) => {
    const presentation = aggregatedData.presentation.presentations?.[index] || {};

    imagePrompts.push({
      cocktailName: cocktail.name,
      prompt: `Professional cocktail photography: ${cocktail.name} cocktail in ${presentation.glassware || 'elegant glass'}, ${presentation.colorProfile || 'vibrant colors'}, ${presentation.garnish || 'sophisticated garnish'}, luxury bar setting, soft dramatic lighting, shallow depth of field, high-end magazine style, photorealistic, 8k quality`,
      style: "photorealistic, professional photography"
    });
  });
}

return {
  json: {
    aggregatedData,
    imagePrompts
  }
};

